.version 7.1
.target sm_80
.address_size 64

.visible .entry gn_kernel(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u32 N,
    .param .u32 C,
    .param .u32 G,
    .param .u32 H,
    .param .u32 W,
    .param .f32 eps
)
{
    // ----- registers -------------------------------------------------
    .reg .pred   %p<5>;
    .reg .u32    %r<33>;
    .reg .u64    %rd<12>;
    .reg .f32    %f<19>;
    .reg .f16    %h<2>;

    // ----- load kernel parameters ------------------------------------
    ld.param.u64    %rd1, [input_ptr];
    ld.param.u64    %rd2, [output_ptr];
    ld.param.u32    %r1, [N];          // batch size
    ld.param.u32    %r2, [C];          // channels
    ld.param.u32    %r3, [G];          // groups
    ld.param.u32    %r4, [H];          // height
    ld.param.u32    %r5, [W];          // width
    ld.param.f32    %f0, [eps];        // epsilon

    // ----- compute block identifiers ---------------------------------
    mov.u32 %r6, %ctaid.x;            // blockIdx.x
    // n = blockIdx.x / G
    div.u32 %r7, %r6, %r3;
    // g = blockIdx.x % G
    mul.lo.u32 %r8, %r7, %r3;
    sub.u32 %r9, %r6, %r8;             // g

    // ----- per‑group constants ---------------------------------------
    // C_per_group = C / G
    div.u32 %r10, %r2, %r3;
    // elems_per_group = C_per_group * H * W
    mul.lo.u32 %r11, %r10, %r4;
    mul.lo.u32 %r12, %r11, %r5;        // total elements in one (n,g) group

    // ----- shared memory for reduction -------------------------------
    .shared .align 4 .f32 sh_sum[256];
    .shared .align 4 .f32 sh_sumsq[256];

    // ----- thread index ---------------------------------------------
    mov.u32 %r13, %tid.x;             // threadIdx.x
    mov.u32 %r14, %ntid.x;            // blockDim.x

    // ----- local accumulators ----------------------------------------
    mov.f32 %f1, 0.0;                 // sum
    mov.f32 %f2, 0.0;                 // sumsq

    // ----- first pass: compute sum & sumsq ---------------------------
    mov.u32 %r15, %r13;               // i = threadIdx.x
first_loop:
    setp.ge.u32 %p1, %r15, %r12;
    @%p1 bra first_done;

    // ---- compute indices inside the group -------------------------
    // HW = H*W
    mul.lo.u32 %r16, %r4, %r5;
    // c_offset = i / HW
    div.u32 %r17, %r15, %r16;
    // rem = i % HW
    mul.lo.u32 %r18, %r17, %r16;
    sub.u32 %r19, %r15, %r18;          // rem

    // h = rem / W
    div.u32 %r20, %r19, %r5;
    // w = rem % W
    mul.lo.u32 %r21, %r20, %r5;
    sub.u32 %r22, %r19, %r21;          // w

    // channel = g * C_per_group + c_offset
    mul.lo.u32 %r23, %r9, %r10;
    add.u32 %r24, %r23, %r17;          // channel

    // flat index = ((n*C + channel) * H + h) * W + w
    mul.lo.u32 %r25, %r7, %r2;         // n*C
    add.u32 %r26, %r25, %r24;          // n*C + channel
    mul.lo.u32 %r27, %r26, %r4;        // *H
    add.u32 %r28, %r27, %r20;          // +h
    mul.lo.u32 %r29, %r28, %r5;        // *W
    add.u32 %r30, %r29, %r22;          // +w

    // load fp16 value
    mul.lo.u64 %rd3, %r30, 2;          // byte offset (2 bytes per half)
    add.u64 %rd4, %rd1, %rd3;
    ld.global.u16 %r31, [%rd4];
    mov.b16 %h0, %r31;
    cvt.f32.f16 %f3, %h0;              // to float32

    // accumulate
    add.f32 %f1, %f1, %f3;
    mul.f32 %f4, %f3, %f3;
    add.f32 %f2, %f2, %f4;

    // i += blockDim.x
    add.u32 %r15, %r15, %r14;
    bra first_loop;
first_done:

    // ----- write local sums to shared memory -------------------------
    st.shared.f32 [sh_sum+%r13*4], %f1;
    st.shared.f32 [sh_sumsq+%r13*4], %f2;
    bar.sync 0;

    // ----- reduction by thread 0 ------------------------------------
    mov.u32 %r31, 0;
    mov.f32 %f5, 0.0;                  // total sum
    mov.f32 %f6, 0.0;                  // total sumsq
reduce_loop:
    setp.ge.u32 %p2, %r31, %r14;
    @%p2 bra reduce_done;
    ld.shared.f32 %f7, [sh_sum+%r31*4];
    ld.shared.f32 %f8, [sh_sumsq+%r31*4];
    add.f32 %f5, %f5, %f7;
    add.f32 %f6, %f6, %f8;
    add.u32 %r31, %r31, 1;
    bra reduce_loop;
reduce_done:

    // broadcast totals to all threads via shared memory slot 0
    st.shared.f32 [sh_sum+0], %f5;
    st.shared.f32 [sh_sumsq+0], %f6;
    bar.sync 0;

    ld.shared.f32 %f9, [sh_sum+0];     // total sum
    ld.shared.f32 %f10, [sh_sumsq+0];  // total sumsq

    // ----- compute mean, variance, inv_std -------------------------
    cvt.f32.u32 %f11, %r12;            // elems_per_group as float
    div.f32 %f12, %f9, %f11;           // mean
    div.f32 %f13, %f10, %f11;          // mean of squares
    mul.f32 %f14, %f12, %f12;          // mean^2
    sub.f32 %f15, %f13, %f14;          // variance
    add.f32 %f16, %f15, %f0;           // variance + eps
    sqrt.approx.f32 %f17, %f16;
    rcp.approx.f32 %f18, %f17;        // 1 / sqrt(var+eps)

    // ----- second pass: write normalized output --------------------
    mov.u32 %r15, %r13;               // i = threadIdx.x again
second_loop:
    setp.ge.u32 %p3, %r15, %r12;
    @%p3 bra second_done;

    // recompute same indices (same code as above)
    mul.lo.u32 %r16, %r4, %r5;         // HW
    div.u32 %r17, %r15, %r16;          // c_offset
    mul.lo.u32 %r18, %r17, %r16;
    sub.u32 %r19, %r15, %r18;          // rem
    div.u32 %r20, %r19, %r5;           // h
    mul.lo.u32 %r21, %r20, %r5;
    sub.u32 %r22, %r19, %r21;          // w
    mul.lo.u32 %r23, %r9, %r10;
    add.u32 %r24, %r23, %r17;          // channel
    mul.lo.u32 %r25, %r7, %r2;         // n*C
    add.u32 %r26, %r25, %r24;          // n*C + channel
    mul.lo.u32 %r27, %r26, %r4;        // *H
    add.u32 %r28, %r27, %r20;          // +h
    mul.lo.u32 %r29, %r28, %r5;        // *W
    add.u32 %r30, %r29, %r22;          // +w

    // load input half
    mul.lo.u64 %rd3, %r30, 2;
    add.u64 %rd4, %rd1, %rd3;
    ld.global.u16 %r31, [%rd4];
    mov.b16 %h0, %r31;
    cvt.f32.f16 %f3, %h0;

    // normalize: (x - mean) * inv_std
    sub.f32 %f3, %f3, %f12;
    mul.f32 %f3, %f3, %f18;

    // convert back to half and store
    cvt.f16.f32 %h1, %f3;
    mov.b16 %r32, %h1;
    mul.lo.u64 %rd5, %r30, 2;
    add.u64 %rd6, %rd2, %rd5;
    st.global.u16 [%rd6], %r32;

    // i += blockDim.x
    add.u32 %r15, %r15, %r14;
    bra second_loop;
second_done:
    ret;
}
